const getContractRecord = (params: IContractParams) =>
  demoContracts.find(
    (item) =>
      item.pageName === params.pageName &&
      item.contractTypeID === params.contractTypeID
  ) ??
  demoContracts.find(
    (item) =>
      item.pageName === params.pageName && item.contractTypeID === undefined
  );

const paginate = <T>(items: T[], page = 1, pageSize = 10) => {
  const start = (page - 1) * pageSize;
  return items.slice(start, start + pageSize);
};

export const getDemoContent = async (
  params: IContractParams
): Promise<IContractResponse> => {
  await wait(DEMO_DELAY_MS);

  const contract = getContractRecord(params);

  if (!contract) {
    return {
      status: false,
      statusCode: 404,
      message: "Content not found.",
      data: {
        isAgreed: false,
        content: "",
        updatedDate: "",
      },
    };
  }

  return {
    status: true,
    statusCode: 200,
    message: "Content fetched successfully!",
    data: contract,
  } as unknown as IContractResponse;
};

export const updateDemoContent = async (
  body: IUpdatedContractBody
): Promise<ILogoutResponse> => {
  await wait(DEMO_DELAY_MS);

  const contract = getContractRecord({
    pageName: body.pageName,
    contractTypeID: body.contractID,
  });

  const now = new Date().toISOString();

  if (contract) {
    contract.content = body.description;
    contract.updatedDate = now;
    contract.contractEnforcementDate =
      body.contractEnforcementDate ?? contract.contractEnforcementDate;
    contract.contractVersion =
      contract.contractVersion !== null ? contract.contractVersion + 1 : null;
  } else {
    demoContracts.push({
      pageName: body.pageName,
      contractTypeID: body.contractID,
      isAgreed: false,
      content: body.description,
      aadhaarNumber: null,
      updatedDate: now,
      contractVersion: 1,
      contractEnforcementDate: body.contractEnforcementDate ?? null,
      contractUserMappingID: null,
    });
  }

  return {
    status: true,
    statusCode: 200,
    data: null,
    message: "Content updated successfully!",
  };
};

export const getDemoContractList = async (
  params: IContractListParams
): Promise<IContractListResponse> => {
  await wait(DEMO_DELAY_MS);

  const searchText = (params.user ?? params.search ?? "").trim().toLowerCase();
  const sourceList = demoContractLists[params.userType] ?? [];
  const filteredList = searchText
    ? sourceList.filter(
      (item) =>
        item.name.toLowerCase().includes(searchText) ||
        item.userCode.toLowerCase().includes(searchText)
    )
    : sourceList;

  return {
    status: true,
    statusCode: 200,
    message: "Content fetched successfully!",
    data: {
      totalCount: filteredList.length,
      contractList: paginate(filteredList, params.page, params.pageSize),
    },
  };
};

