export const updateDemoContractStatus = async (
  body: IUpdatedContractStatusBody
): Promise<APIResponseEntity> => {
  await wait(DEMO_DELAY_MS);

  if (body.status) {
    demoContracts.forEach((item) => {
      if (item.pageName === ContractType.CONTRACT) {
        item.isAgreed = true;
      }
    });
  }

  return {
    status: true,
    statusCode: 200,
    message: "Contract status updated successfully!",
  };
};

